require __DIR__.'/includes/config.php'; lab_sensitive_page('pago.php','Pasarela de pago','notice');$pdo=db();$success=null;$error=null;$paymentId=null;$prefillAccount='';$prefillAmount='';$invoiceId=(int)($_GET['factura']??($_POST['factura_id']??0));
$logged=!empty($_SESSION['user']);$uid=$logged?(int)$_SESSION['user']['id']:null;$linked=null;$invoice=null;
if($logged){$requested=(int)($_GET['cuenta']??0);if($requested){$q=$pdo->prepare('SELECT * FROM cuentas_servicio WHERE id=? AND usuario_id=? LIMIT 1');$q->execute([$requested,$uid]);$linked=$q->fetch();}if(!$linked){$q=$pdo->prepare('SELECT * FROM cuentas_servicio WHERE usuario_id=? ORDER BY id LIMIT 1');$q->execute([$uid]);$linked=$q->fetch();}if($linked)$prefillAccount=$linked['cuenta'];}
if($invoiceId && $logged){$q=$pdo->prepare('SELECT f.* FROM facturas f JOIN cuentas_servicio c ON c.id=f.cuenta_id WHERE f.id=? AND c.usuario_id=?');$q->execute([$invoiceId,$uid]);$invoice=$q->fetch();if($invoice){$prefillAmount=$invoice['saldo'];}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $cuenta=trim($_POST['cuenta']??'');$monto=(float)($_POST['monto']??0);$metodo=$_POST['metodo']??'Tarjeta';$ultimos4=preg_replace('/\D/','',$_POST['ultimos4']??'');$ultimos4=substr($ultimos4,-4);$postedInvoice=(int)($_POST['factura_id']??0);
 if($cuenta===''||$monto<=0){$error='Verifica el número de cuenta y el importe.';} else {
  $q=$pdo->prepare('SELECT * FROM cuentas_servicio WHERE cuenta=? LIMIT 1');$q->execute([$cuenta]);$cs=$q->fetch();
  if(!$cs){$error='La cuenta de servicio no existe.';} else {
   $f=null;if($postedInvoice){$q=$pdo->prepare('SELECT * FROM facturas WHERE id=? AND cuenta_id=? LIMIT 1');$q->execute([$postedInvoice,$cs['id']]);$f=$q->fetch();if(!$f)$error='El recibo seleccionado no corresponde a la cuenta.';}
   if(!$error){try{$pdo->beginTransaction();$ref='PAY-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));$st=$pdo->prepare('INSERT INTO pagos (usuario_id,cuenta_id,factura_id,referencia,monto,metodo,ultimos4,estado) VALUES (?,?,?,?,?,?,?,\'Aplicado\')');$st->execute([$uid,$cs['id'],$f['id']??null,$ref,$monto,$metodo,$ultimos4?:null]);$paymentId=(int)$pdo->lastInsertId();if($f){$new=max(0,(float)$f['saldo']-$monto);$state=$new<=0.009?'Pagada':'Parcial';$pdo->prepare('UPDATE facturas SET saldo=?,estado=? WHERE id=?')->execute([$new,$state,$f['id']]);}$q=$pdo->prepare("SELECT COALESCE(SUM(saldo),0) FROM facturas WHERE cuenta_id=? AND estado<>'Pagada'");$q->execute([$cs['id']]);$totalSaldo=(float)$q->fetchColumn();$pdo->prepare('UPDATE cuentas_servicio SET saldo=? WHERE id=?')->execute([$totalSaldo,$cs['id']]);if($uid){$pdo->prepare('INSERT INTO notificaciones (usuario_id,titulo,mensaje,tipo,leida) VALUES (?,?,?,?,0)')->execute([$uid,'Pago aplicado','Se registró un pago por $'.number_format($monto,2).' con referencia '.$ref.'.','facturacion']);}$pdo->commit();$success=$ref;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='No fue posible registrar la operación.';}}
  }
 }
